<!doctype html><html lang="de"><head><meta charset="utf-8"><title>Rechnung #{{ $order->id }}</title><style>body{font-family:Arial;max-width:800px;margin:40px auto;color:#26362a}header{display:flex;justify-content:space-between;border-bottom:3px solid #315d38;padding-bottom:25px}img{width:180px}table{width:100%;border-collapse:collapse;margin:35px 0}th,td{padding:12px;border-bottom:1px solid #ddd;text-align:left}.total{text-align:right;font-size:22px}.print{padding:12px 18px;background:#315d38;color:white;border:0;border-radius:8px}@media print{.print{display:none}}</style></head><body><button class="print" onclick="print()">Als PDF drucken / speichern</button><header><img src="{{ asset('assets/images/naturmarkt-logo.svg') }}"><div><strong>Rechnung #{{ $order->id }}</strong><br>{{ date('d.m.Y',strtotime($order->created_at)) }}</div></header><h2>Rechnung an</h2><p>{{ $order->customer_name }}<br>{{ $order->street }}<br>{{ $order->postal_code }} {{ $order->city }}<br>{{ $order->email }}</p><table><tr><th>Produkt</th><th>Menge</th><th>Einzelpreis</th><th>Summe</th></tr>@foreach($order->items as $item)<tr><td>{{ $item['name']??'Produkt' }}</td><td>{{ $item['quantity']??1 }}</td><td>{{ number_format($item['unit_price']??0,2,',','.') }} €</td><td>{{ number_format($item['line_total']??0,2,',','.') }} €</td></tr>@endforeach<tr><td colspan="3">Versand</td><td>{{ number_format($order->shipping,2,',','.') }} €</td></tr>@if($order->discount)<tr><td colspan="3">Rabatt</td><td>-{{ number_format($order->discount,2,',','.') }} €</td></tr>@endif</table><p class="total"><strong>Gesamt: {{ number_format($order->total,2,',','.') }} €</strong></p><small>Vor dem Verkaufsstart um vollständige Unternehmens- und Steuerangaben ergänzen.</small></body></html>
